def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor, as_completed

    if not cmd:
        raise ValueError("Command must be provided.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")
    if _max_length < 0:
        raise ValueError("Max length must be non-negative.")

    def run_command(args: tuple[str, ...]) -> subprocess.CompletedProcess:
        return subprocess.run(args, capture_output=True, text=False)

    def split_into_chunks(lst: Sequence[str], n: int) -> list[list[str]]:
        k, m = divmod(len(lst), n)
        return [lst[i * k + min(i, m):(i + 1) * k + min(i + 1, m)] for i in range(n)]

    commands = split_into_chunks(varargs, target_concurrency)
    commands = [(cmd + tuple(chunk)) for chunk in commands]

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = {executor.submit(run_command, cmd): cmd for cmd in commands}
        results = [future.result() for future in as_completed(futures)]

    exit_code = 0
    output = b""
    for result in results:
        if result.returncode != 0:
            exit_code = result.returncode
        output += result.stdout + result.stderr

    return exit_code, output

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    import shlex
    from concurrent.futures import ThreadPoolExecutor, as_completed

    if not cmd:
        raise ValueError("Command cannot be empty.")
    if target_concurrency <= 0:
        raise ValueError("Target concurrency must be greater than zero.")
    if _max_length <= 0:
        raise ValueError("Max length must be greater than zero.")

    def run_command(args: list[str]) -> subprocess.CompletedProcess:
        full_cmd = list(cmd) + args
        if color and os.name == 'posix':
            return subprocess.run(['stdbuf', '-oL'] + full_cmd, capture_output=True, text=False, stderr=subprocess.STDOUT, close_fds=True, start_new_session=True)
        else:
            return subprocess.run(full_cmd, capture_output=True, text=False, stderr=subprocess.STDOUT)

    all_args = list(varargs)
    partitions = [all_args[i:i + _max_length] for i in range(0, len(all_args), _max_length)]

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_args = {executor.submit(run_command, args): args for args in partitions}
        for future in as_completed(future_to_args):
            args = future_to_args[future]
            try:
                result = future.result()
                results.append(result)
            except Exception as exc:
                print(f"Command with args {args} generated an exception: {exc}")

    exit_code = 0
    output = b""
    for result in results:
        if result.returncode != 0:
            exit_code = result.returncode
        output += result.stdout

    return exit_code, output

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        if not isinstance(seq, Sequence):
            raise ValueError("Input must be a sequence")
        sorted_seq = sorted(seq)
        shuffled = []
        mid = len(sorted_seq) // 2
        for i in range(mid):
            shuffled.append(sorted_seq[i])
            shuffled.append(sorted_seq[mid + i])
        if len(sorted_seq) % 2 != 0:
            shuffled.append(sorted_seq[-1])
        return shuffled
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

