    if not cmd:
        raise ValueError("Command tuple cannot be empty")

    # Convert the command tuple to a list for mutability
    cmd_list = list(cmd)

    # Check if the first element is a script with a shebang that needs fixing
    if cmd_list[0].endswith('.py'):
        try:
            with open(cmd_list[0], 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!') and 'python' in first_line:
                    # If the shebang is present, prepend the script with 'python'
                    cmd_list = ['python', cmd_list[0]] + cmd_list[1:]
        except FileNotFoundError:
            raise FileNotFoundError(f"The script {cmd_list[0]} does not exist")
        except Exception as e:
            raise Exception(f"An error occurred while reading the script {cmd_list[0]}: {e}")

    # Convert the list back to a tuple
    return tuple(cmd_list)

