    import os
    import subprocess

    if not cmd or not isinstance(cmd, tuple):
        raise ValueError("cmd must be a non-empty tuple of strings")

    normalized_cmd = list(cmd)

    # Check if the first element is a script with a shebang
    script_path = normalized_cmd[0]
    if os.name == 'nt' and os.path.isfile(script_path):
        with open(script_path, 'r', encoding='utf-8') as file:
            first_line = file.readline().strip()
            if first_line.startswith('#!'):
                # Shebang found, parse the interpreter
                interpreter = first_line[2:].split()[0]
                # Convert to Windows style path if necessary
                if interpreter.startswith('/'):
                    interpreter = subprocess.check_output(['cygpath', '-w', interpreter]).decode().strip()
                # Replace the script with the interpreter and the script as arguments
                normalized_cmd = [interpreter, script_path] + normalized_cmd[1:]

    return tuple(normalized_cmd)

