def extostr(cls, e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("The provided object is not an exception instance.")
    if not isinstance(max_level, int) or not isinstance(max_path_level, int):
        raise ValueError("max_level and max_path_level must be integers.")
    if max_level < 0 or max_path_level < 0:
        raise ValueError("max_level and max_path_level must be non-negative integers.")

    try:
        exc_type = type(e).__name__
        exc_msg = str(e)
        traceback = []
        import traceback as tb
        for frame_info in tb.extract_tb(e.__traceback__, limit=max_level):
            path_parts = frame_info.filename.split('/')
            truncated_path = '/'.join(path_parts[-max_path_level:])
            traceback.append(f"  File \"{truncated_path}\", line {frame_info.lineno}, in {frame_info.name}")
            if frame_info.line:
                traceback.append(f"    {frame_info.line.strip()}")
        return f"{exc_type}: {exc_msg}\n" + "\n".join(traceback)
    except Exception as exc:
        return f"Failed to format exception: {exc}"

