def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Create a graph where edges represent the orderings
    graph = {}
    in_degree = {}

    for order in orderings:
        for i in range(len(order)):
            if order[i] not in graph:
                graph[order[i]] = set()
                in_degree[order[i]] = 0
            if i + 1 < len(order):
                if order[i + 1] not in graph:
                    graph[order[i + 1]] = set()
                    in_degree[order[i + 1]] = 0
                if order[i + 1] not in graph[order[i]]:
                    graph[order[i]].add(order[i + 1])
                    in_degree[order[i + 1]] += 1

    # Topological sort using Kahn's algorithm
    queue = [node for node in in_degree if in_degree[node] == 0]
    result = []

    while queue:
        if len(queue) > 1:
            raise ValueError("Merging orderings results in ambiguous ordering")
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(in_degree):
        raise ValueError("Orderings contain cycles or are inconsistent")

    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved"""
    if not orderings:
        return []

    # Create a graph where each node points to the next element in the ordering
    graph = {}
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            if ordering[i] not in graph:
                graph[ordering[i]] = []
            graph[ordering[i]].append(ordering[i + 1])

    # Find all starting points (nodes with no incoming edges)
    all_items = set(item for ordering in orderings for item in ordering)
    start_points = all_items - {item for items in graph.values() for item in items}

    # Perform a topological sort to merge the orderings
    result = []
    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        if node in graph:
            for neighbor in graph[node]:
                dfs(neighbor)
        result.append(node)

    for start in start_points:
        dfs(start)

    # Reverse the result to get the correct order
    result.reverse()

    # Ensure all items are included in the result
    return [item for item in result if item in all_items]

