def minimalBases(classes):
    try:
        # Create a dictionary to track the inheritance relationships
        inheritance_map = {}
        for cls in classes:
            inheritance_map[cls] = set(cls.__bases__)

        # Function to check if a class is redundant
        def is_redundant(cls):
            for base in inheritance_map[cls]:
                if base in classes:
                    return True
            return False

        # Remove redundant classes
        minimal_classes = [cls for cls in classes if not is_redundant(cls)]

        # Sort the minimal classes based on their MRO
        minimal_classes.sort(key=lambda cls: cls.__mro__)

        return minimal_classes
    except (AttributeError, TypeError):
        # Handle cases where input is not a list of classes
        raise ValueError("Input must be a list of class objects.")
    except Exception as e:
        # Catch any other unexpected exceptions
        raise RuntimeError(f"An unexpected error occurred: {str(e)}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, list):
        raise ValueError("Input must be a list of classes")

    # Use a set to track unique classes and a list to maintain order
    seen = set()
    minimal = []

    for cls in classes:
        if not inspect.isclass(cls):
            raise ValueError("All elements in the list must be class types")
        # Check if the class or any of its superclasses are already in minimal
        if cls not in seen:
            # Add the class to seen set
            seen.add(cls)
            # Check and remove subclasses already in minimal
            minimal = [c for c in minimal if not issubclass(cls, c)]
            # Add the current class to minimal
            minimal.append(cls)

    # Reorder minimal to ensure MRO consistency
    return sorted(minimal, key=lambda x: (len(x.mro()), x.mro()))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track seen classes and a list to maintain order
        seen = set()
        minimal_bases = []

        # Iterate over the classes in reverse to maintain the MRO (Method Resolution Order)
        for cls in reversed(classes):
            # Check if the class is not already in seen
            if cls not in seen:
                # Add the class to the seen set and insert it at the beginning of minimal_bases
                seen.add(cls)
                minimal_bases.insert(0, cls)
            else:
                # If the class is already in seen, check its subclasses
                for subclass in cls.__subclasses__():
                    if subclass in seen:
                        seen.remove(subclass)
                        minimal_bases.remove(subclass)

        return minimal_bases

    except AttributeError:
        # Handle cases where the input list contains non-class objects
        raise ValueError("All elements in the classes list must be class objects.")
    except Exception as e:
        # Handle any other unexpected exceptions
        raise RuntimeError(f"An unexpected error occurred: {str(e)}")

