        raise ValueError("observer_schema and response must have the same length")

    for schema_item, resp_item in zip(observer_schema, response):
        if isinstance(schema_item, dict) and isinstance(resp_item, dict):
            # Recursively update dictionary if both schema_item and resp_item are dictionaries
            update_last_applied_manifest_dict_from_resp({}, schema_item, resp_item)
        elif isinstance(schema_item, list) and isinstance(resp_item, list):
            # Recursively update list if both schema_item and resp_item are lists
            update_last_applied_manifest_list_from_resp([], schema_item, resp_item)
        else:
            # Initialize the value in last_applied_manifest if not yet present
            for index, item in enumerate(schema_item):
                if index >= len(last_applied_manifest):
                    last_applied_manifest.append(None)
                if last_applied_manifest[index] is None:
