    if len(last_applied_manifest) != len(observer_schema) or len(observer_schema) != len(response):
        raise ValueError("All input lists must be of the same length.")

    for i in range(len(observer_schema)):
        observed_field = observer_schema[i]
        resp_entry = response[i]

        if isinstance(observed_field, dict) and isinstance(resp_entry, dict) and isinstance(last_applied_manifest[i], dict):
            # Recursively update dictionary fields
            for key in observed_field:
                if key not in last_applied_manifest[i]:
                    last_applied_manifest[i][key] = resp_entry.get(key)
        elif isinstance(observed_field, list) and isinstance(resp_entry, list) and isinstance(last_applied_manifest[i], list):
            # Recursively update list fields
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observed_field, resp_entry)
        elif observed_field is not None and last_applied_manifest[i] is None:
            # Initialize field if not present in last_applied_manifest
            last_applied_manifest[i] = resp_entry

