):
    for key, schema in observer_schema.items():
        if 'fields' in schema and isinstance(schema['fields'], dict):
            # Recursively update for nested structures
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            if key not in response:
                raise KeyError(f"The observed field '{key}' is not present in the Kubernetes response")
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema['fields'], response[key]
            )
        else:
            # Initialize the value if not present in last_applied_manifest
            if key not in last_applied_manifest and key in response:
                last_applied_manifest[key] = response[key]
            elif key not in response:
                raise KeyError(f"The observed field '{key}' is not present in the Kubernetes response")

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    if not isinstance(last_applied_manifest, dict) or not isinstance(observer_schema, dict) or not isinstance(response, dict):
        raise TypeError("All inputs must be dictionaries")

    for field, schema in observer_schema.items():
        if field not in last_applied_manifest:
            if field in response:
                last_applied_manifest[field] = response[field]
            else:
                raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")
        if isinstance(schema, dict) and isinstance(last_applied_manifest.get(field), dict) and isinstance(response.get(field), dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response.get(field, {}))
        elif isinstance(schema, list) and isinstance(last_applied_manifest.get(field), list) and isinstance(response.get(field), list):
            for item_schema in schema:
                if isinstance(item_schema, dict):
                    for resp_item in response.get(field, []):
                        item_match = False
                        for manifest_item in last_applied_manifest[field]:
                            if all(manifest_item.get(k) == resp_item.get(k) for k in item_schema if k != '*'):
                                update_last_applied_manifest_dict_from_resp(manifest_item, item_schema, resp_item)
                                item_match = True
