        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]

        if isinstance(schema, dict) and isinstance(response[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response[field])

def generate_default_observer_schema(app):
    try:
        observer_schema = {}
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application object does not contain a valid spec.manifest")

        for resource in app.spec.manifest:
            # Check if the resource already has a custom observer schema
            if resource.get('observer_schema') is None:
                # Generate a default observer schema for the resource
                default_schema = {
                    "fields": {
                        "status": {
                            "kind": "string"
                        },
                        "replicas": {
                            "kind": "integer"
                        }
                    }
                }
                # Assign the default schema to the resource
                if 'observer_schema' not in resource:
                    resource['observer_schema'] = {}
                resource['observer_schema'].update(default_schema)

        observer_schema['resources'] = app.spec.manifest
        return observer_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not app or not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Invalid application object or missing manifest")

        default_schema = {}
        for resource_type, resources in app.spec.manifest.items():
            if not isinstance(resources, list):
                raise ValueError(f"Manifest for {resource_type} is not a list")

            for resource in resources:
                if not isinstance(resource, dict) or 'metadata' not in resource:
                    raise ValueError(f"Invalid resource format for {resource_type}")

                resource_name = resource['metadata'].get('name')
                if not resource_name:
                    raise ValueError(f"Resource for {resource_type} is missing a name")

                if resource_type not in app.spec.observer_schema:
                    if resource_type not in default_schema:
                        default_schema[resource_type] = {}
                    default_schema[resource_type][resource_name] = {
                        "kind": resource_type,
                        "name": resource_name
                    }

        return default_schema

    except Exception as e:
        print(f"Error generating default observer schema: {e}")
        return {}

