def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if not isinstance(sql, (str, bytes)):
			raise ValueError("SQL must be of type str or bytes")

		if not isinstance(params, (dict, list, tuple)):
			raise ValueError("Parameters must be of type dict, list, or tuple")

		if isinstance(params, dict):
			# Assuming the in-style parameter style is named (e.g., :name)
			out_params = {}
			for i, (key, value) in enumerate(params.items()):
				new_key = f":param{i}"
				out_params[new_key] = value
				sql = sql.replace(f":{key}", new_key)
		else:
			# Assuming the in-style parameter style is ordinal (e.g., %s)
			out_params = list(params)
			sql = sql.replace('%s', '%(param)d')
			for i in range(len(out_params)):
				sql = sql.replace(f'%(param)d', f':param{i}', 1)

		return sql, out_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, (str, bytes)) and sql:
        if isinstance(params, (dict, list, tuple)):
            if params and isinstance(params, dict):
                # Assuming out-style is using named parameters with % style
                placeholder = '%(' + '%s)s'
                formatted_sql = sql
                for key in params.keys():
                    formatted_sql = formatted_sql.replace(f':{key}', placeholder % key)
                return formatted_sql, dict(params)
            elif params and isinstance(params, (list, tuple)):
                # Assuming out-style is using ordinal parameters with % style
                formatted_sql = sql
                formatted_sql = formatted_sql.replace(':', '%')
                return formatted_sql, list(params)
            else:
                # Empty params
                return sql, params
        else:
            raise ValueError("params must be a Mapping or Sequence")
    else:
        raise ValueError("sql must be a non-empty string or bytes")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, Mapping):
            out_params = {f":{key}": value for key, value in params.items()}
            formatted_sql = sql
            for key in params:
                placeholder = f"%({key})s"
                out_placeholder = f":{key}"
                formatted_sql = formatted_sql.replace(placeholder, out_placeholder)
        elif isinstance(params, Sequence):
            out_params = [value for value in params]
            formatted_sql = sql
            count = 1
            while f"%({count})s" in formatted_sql:
                formatted_sql = formatted_sql.replace(f"%({count})s", f":{count}")
                count += 1
        else:
            raise ValueError("params must be either a Mapping or a Sequence")
        return formatted_sql, out_params
    except Exception as e:
        raise ValueError(f"Error formatting SQL: {e}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, (list, tuple)):
            # Assuming ordinal parameters (e.g., %s, %s)
            # PostgreSQL uses %s for placeholders, so we need to convert to $1, $2, etc.
            formatted_sql = sql
            for i in range(1, len(params) + 1):
                placeholder = f"%s"
                new_placeholder = f"${i}"
                formatted_sql = formatted_sql.replace(placeholder, new_placeholder, 1)
            return formatted_sql, list(params)
        elif isinstance(params, dict):
            # Assuming named parameters (e.g., :name, :age)
            # PostgreSQL uses %s for placeholders, so we need to convert to %(name)s, %(age)s, etc.
            formatted_sql = sql
            for key in params:
                placeholder = f":{key}"
                new_placeholder = f"%({key})s"
                formatted_sql = formatted_sql.replace(placeholder, new_placeholder)
            return formatted_sql, {k: v for k, v in params.items()}
        else:
            raise ValueError("Parameters must be a list, tuple, or dictionary.")
    except Exception as e:
        raise ValueError(f"An error occurred during SQL formatting: {e}")

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		if not isinstance(sql, (str, bytes)):
			raise ValueError("sql must be of type str or bytes")

		if not isinstance(many_params, Iterable):
			raise ValueError("many_params must be an iterable")

		in_style = getattr(self, 'SQLParams', None) and getattr(self.SQLParams, 'in_style', None)
		if in_style is None:
			raise AttributeError("self.SQLParams.in_style is not defined")

		is_named_style = in_style in {'named', ':', '@', '%'}
		is_ordinal_style = in_style in {'qmark', 'numeric', 'format', 'pyformat'}

		if not (is_named_style or is_ordinal_style):
			raise ValueError(f"Unsupported in-style parameter: {in_style}")

		out_style = getattr(self, 'SQLParams', None) and getattr(self.SQLParams, 'out_style', None)
		if out_style is None:
			raise AttributeError("self.SQLParams.out_style is not defined")

		if out_style not in {'named', 'qmark', 'numeric', 'format', 'pyformat'}:
			raise ValueError(f"Unsupported out-style parameter: {out_style}")

		if out_style == in_style:
			return sql, list(many_params)

		parameter_map = {
			'named': ('{', '}'),
			':': (':', ''),
			'@': ('@', ''),
			'%': ('%', ''),
			'qmark': ('?', ''),
			'numeric': ('%s', ''),
			'format': ('%s', ''),
			'pyformat': ('%(', ')s'),
		}

		in_prefix, in_suffix = parameter_map[in_style]
		out_prefix, out_suffix = parameter_map[out_style]

		def convert_param(key):
			if out_style == 'numeric':
				return f'{out_prefix}{i + 1}{out_suffix}'
			elif out_style == 'named':
				if isinstance(key, str) and key.startswith(in_prefix):
					return f'{out_prefix}{key[len(in_prefix):-len(in_suffix) if in_suffix else len(in_prefix)]}{out_suffix}'
				return f'{out_prefix}{key}{out_suffix}'
			else:
				return f'{out_prefix}{key}{out_suffix}'

		def replace_params(query, params):
			keys = list(params.keys()) if isinstance(params, dict) else range(len(params))
			for i, key in enumerate(keys):
				search = f'{in_prefix}{key}{in_suffix}'
				query = query.replace(search, convert_param(key))
			return query

		out_sql = sql
		out_params = []
		out_type = dict if isinstance(next(iter(many_params), {}), dict) else list

		for i, params in enumerate(many_params):
			if out_type is dict and not isinstance(params, dict):
				raise ValueError(f"params at index {i} must be a dict")
			if out_type is list and not isinstance(params, (list, tuple)):
				raise ValueError(f"params at index {i} must be a list or tuple")

			if in_style == 'named':
				out_sql = replace_params(out_sql, params)
				out_params.append({convert_param(k).strip(out_prefix).strip(out_suffix): v for k, v in params.items()})
			else:
				converted_params = []
				for j in range(len(params)):
					converted_params.append(params[j])
				out_sql = replace_params(out_sql, dict(enumerate(params)))
				out_params.append(converted_params if out_style != 'named' else {f'{out_prefix}{j + 1}{out_suffix}': p for j, p in enumerate(converted_params)})

		return out_sql, out_params

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		# Assuming in_style is a class attribute indicating the style of input parameters
		in_style = getattr(self, 'SQLParams', None) and getattr(self.SQLParams, 'in_style', None)
		if in_style not in ['named', 'ordinal']:
			raise ValueError("SQLParams.in_style must be either 'named' or 'ordinal'")

		# Define out-style based on in-style
		out_style = 'qmark'  # Assuming qmark is the out-style parameter placeholder

		if in_style == 'named':
			# Named style uses :name
			param_pattern = re.compile(r':([a-zA-Z_][a-zA-Z0-9_]*)')
			param_replacer = lambda match: '?'
		elif in_style == 'ordinal':
			# Ordinal style uses ?
			param_pattern = re.compile(r'\?')
			param_replacer = lambda match: '?'
		else:
			raise ValueError("Unsupported in-style parameter format")

		# Convert sql and parameters
		def convert_params(params):
			if in_style == 'named':
				return list(params.values())
			elif in_style == 'ordinal':
				return list(params)
			else:
				raise ValueError("Unsupported in-style parameter format")

		# Replace in-style parameters with out-style
		new_sql = param_pattern.sub(param_replacer, sql)
		new_params = [convert_params(params) for params in many_params]

		return new_sql, new_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
