def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    from os.path import basename,.splitext

    try:
        if not isinstance(xmls, list):
            raise ValueError("xmls must be a list of XML filenames.")
        if not isinstance(files, list):
            raise ValueError("files must be a list of file paths.")

        grouped_files = {xml: [] for xml in xmls}

        for file in files:
            file_base = basename(file)
            for xml in xmls:
                xml_base, _ = splitext(basename(xml))
                if file_base.startswith(xml_base):
                    grouped_files[xml].append(file)
                    break

        return {xml: Package(files=grouped_files[xml]) for xml in xmls if grouped_files[xml]}

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

