def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    if not isinstance(issue, str):
        raise ValueError("Input must be a string")

    issue = issue.strip()
    number = None
    supplement = None
    issue_lower = issue.lower()

    # Check for number
    if issue_lower[0].isdigit():
        temp_number = []
        for char in issue:
            if char.isdigit() or char == '-':
                temp_number.append(char)
            else:
                break
        number = ''.join(temp_number)
        issue = issue[len(number):].strip()

    # Check for supplement keywords
    supplement_keywords = ['suppl', 'supp', 'spe', 'pr', 's']
    for keyword in supplement_keywords:
        if keyword in issue_lower:
            supplement = 'suppl'
            issue = issue.lower().replace(keyword, '').strip()
            break

    # Check for any remaining numbers after supplement keywords
    if supplement and issue:
        temp_supplement_number = []
        for char in issue:
            if char.isdigit() or char == '-':
                temp_supplement_number.append(char)
            else:
                break
        if temp_supplement_number:
            supplement += ' ' + ''.join(temp_supplement_number)

    if not number:
        raise ValueError("Could not extract a valid number from issue element")

    return number, supplement

