def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if not isinstance(expr, tuple) or len(expr) != 3:
            return expr
        op, left, right = expr

        if op == '&':
            if right == ('|', left, _) or right == ('|', _, left):
                return left
            if right == ('|', ('~', left), _):
                return ('&', left, _)
            if right == ('|', _, ('~', left)):
                return ('&', left, _)
        elif op == '|':
            if right == ('&', left, _) or right == ('&', _, left):
                return left
            if right == ('&', ('~', left), _):
                return ('|', left, _)
            if right == ('&', _, ('~', left)):
                return ('|', left, _)
        return expr

    return [apply_absorption(expr) for expr in args]

