def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    try:
        # Convert the UTC datetime to the timezone of self
        local_dt = self.fromutc(dt)

        # Check for ambiguous times in the new timezone
        fold = dt.fold
        new_fold = 0
        if self.localize(local_dt.replace(fold=0), is_dst=None) == self.localize(local_dt.replace(fold=1), is_dst=None):
            # If there's a choice between two possible datetimes, use the fold attribute
            new_fold = fold

        return local_dt.replace(fold=new_fold)
    except Exception as e:
        raise ValueError(f"Error converting datetime to local timezone: {e}")

def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("The input must be a datetime object.")
    if dt.tzinfo is None:
        raise ValueError("The datetime object must be timezone-aware.")

    # Check for fold state (ambiguous time in a timezone, e.g., during daylight saving time transitions)
    fold = 0
    if dt.fold == 1:
        fold = 1

    # Convert the datetime to the new timezone
    new_dt = self.localize(dt.replace(tzinfo=None), is_dst=fold)
    return new_dt

def _fromutc(self, dt):
    if not dt.tzinfo:
        raise ValueError("The datetime object provided is not timezone-aware.")

    # Determine if the datetime is in the fold state
    local_dt = dt.astimezone(self)
    fold_dt = local_dt.replace(fold=1)

    # Compare the original and the fold datetime to check if they represent the same time
    if local_dt.utcoffset() == fold_dt.utcoffset():
        # If they are the same, it means the original datetime is in the fold state
        local_dt = fold_dt

    return self.localize(local_dt, is_dst=None)

def normalized(self):
    try:
        from dateutil.relativedelta import relativedelta
    except ImportError:
        raise ImportError("dateutil module is not installed. Please install it to use this method.")

    # Initialize a new relativedelta object to accumulate the normalized values
    normalized_delta = relativedelta()

    # Normalize days and hours
    if self.days is not None:
        days_int = int(self.days)
        normalized_delta.days = days_int
        hours_from_days = (self.days - days_int) * 24
        if self.hours is not None:
            normalized_delta.hours = int(self.hours + hours_from_days)
        else:
            normalized_delta.hours = int(hours_from_days)
    elif self.hours is not None:
        hours_int = int(self.hours)
        normalized_delta.hours = hours_int
        days_from_hours = (self.hours - hours_int) / 24
        if self.days is not None:
            normalized_delta.days = int(self.days + days_from_hours)
        else:
            normalized_delta.days = int(days_from_hours)

    # Normalize hours and minutes
    if self.hours is not None:
        hours_int = int(self.hours)
        normalized_delta.hours = hours_int
        minutes_from_hours = (self.hours - hours_int) * 60
        if self.minutes is not None:
            normalized_delta.minutes = int(self.minutes + minutes_from_hours)
        else:
            normalized_delta.minutes = int(minutes_from_hours)
    elif self.minutes is not None:
        minutes_int = int(self.minutes)
        normalized_delta.minutes = minutes_int
        hours_from_minutes = (self.minutes - minutes_int) / 60
        if self.hours is not None:
            normalized_delta.hours = int(self.hours + hours_from_minutes)
        else:
            normalized_delta.hours = int(hours_from_minutes)

    # Normalize minutes and seconds
    if self.minutes is not None:
        minutes_int = int(self.minutes)
        normalized_delta.minutes = minutes_int
        seconds_from_minutes = (self.minutes - minutes_int) * 60
        if self.seconds is not None:
            normalized_delta.seconds = int(self.seconds + seconds_from_minutes)
        else:
            normalized_delta.seconds = int(seconds_from_minutes)
    elif self.seconds is not None:
        seconds_int = int(self.seconds)
        normalized_delta.seconds = seconds_int
        minutes_from_seconds = (self.seconds - seconds_int) / 60
        if self.minutes is not None:
            normalized_delta.minutes = int(self.minutes + minutes_from_seconds)
        else:
            normalized_delta.minutes = int(minutes_from_seconds)

    # Normalize seconds and microseconds
    if self.seconds is not None:
        seconds_int = int(self.seconds)
        normalized_delta.seconds = seconds_int
        microseconds_from_seconds = (self.seconds - seconds_int) * 1_000_000
        if self.microseconds is not None:
            normalized_delta.microseconds = int(self.microseconds + microseconds_from_seconds)
        else:
            normalized_delta.microseconds = int(microseconds_from_seconds)
    elif self.microseconds is not None:
        microseconds_int = int(self.microseconds)
        normalized_delta.microseconds = microseconds_int
        seconds_from_microseconds = (self.microseconds - microseconds_int) / 1_000_000
        if self.seconds is not None:
            normalized_delta.seconds = int(self.seconds + seconds_from_microseconds)
        else:
            normalized_delta.seconds = int(seconds_from_microseconds)

    return normalized_delta

def normalized(self):
    try:
        from dateutil.relativedelta import relativedelta
        # Normalize the relativedelta object to ensure all attributes are integers
        days = int(self.days + self.seconds // 86400)
        seconds = self.seconds % 86400
        hours = int(seconds // 3600)
        minutes = int((seconds % 3600) // 60)
        seconds = int(seconds % 60)
        return relativedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)
    except Exception as e:
        raise ValueError(f"Error normalizing relativedelta: {e}")

