def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not commands:
        raise ValueError("Commands list cannot be empty.")
    if not isinstance(commands, list):
        raise TypeError("Commands must be a list.")
    if not all(isinstance(cmd, str) for cmd in commands):
        raise TypeError("All commands must be strings.")
    if not isinstance(args, list):
        raise TypeError("Arguments must be a list.")
    if not all(isinstance(arg, str) for arg in args):
        raise TypeError("All arguments must be strings.")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("Cwd must be a string or None.")
    if not isinstance(verbose, bool):
        raise TypeError("Verbose must be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise TypeError("Hide_stderr must be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise TypeError("Env must be a dictionary or None.")

    if cwd and not os.path.isdir(cwd):
        raise ValueError(f"Cwd '{cwd}' is not a valid directory.")

    full_command = commands + args
    try:
        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)

            if verbose:
                print(output)

            return output

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error executing command: {e}")
        raise
    except FileNotFoundError as e:
        if verbose:
            print(f"Command not found: {e}")
        raise
    except Exception as e:
        if verbose:
            print(f"An unexpected error occurred: {e}")
        raise

