def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.root is the starting point of the hierarchy
        stack = [self.root]

        while stack:
            current = stack.pop()
            num_objects += 1

            if validate_objects:
                if not current.is_valid():
                    if show_warnings:
                        print(f"Warning: {current} is not valid.")
                    continue

            if check_digests:
                if not current.check_digest():
                    if show_warnings:
                        print(f"Warning: Digest mismatch for {current}.")
                    continue

            good_objects += 1

            # Assuming current.children returns a list of child objects
            stack.extend(current.children)

    except AttributeError as e:
        if show_warnings:
            print(f"Warning: Attribute error during validation - {e}")
    except Exception as e:
        if show_warnings:
            print(f"Warning: An error occurred during validation - {e}")

    return num_objects, good_objects

