                merged_value.append((merged_key, merged_value_node))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key][1] = merge_values(key_node, merged_dict[key][1], value_node)
        else:
            merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

