def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.commands.borgmatic as borgmatic_command
        import argparse
        import sys

        # Create a dummy formatter to extract information without printing to stdout
        class DummyFormatter(argparse.HelpFormatter):
            def _format_action(self, action):
                return argparse.HelpFormatter._format_action(self, action)

        # Get the top-level parser
        parser = borgmatic_command.parsers().get_parser()
        formatter = DummyFormatter(width=argparse._HelpMessageAction.DEFAULT_HELP_WIDTH)

        # Extract commands
        commands = []
        for action in parser._actions:
            if action.choices:
                commands.extend(action.choices.keys())

        # Extract options for each command
        command_options = {command: set() for command in commands}
        for command in commands:
            command_parser = borgmatic_command.parsers().get_parser(prog=command)
            for action in command_parser._actions:
                for option in action.option_strings:
                    command_options[command].add(option)

        # Start writing the bash completion script
        completion_script = f"_borgmatic_completion() {{
    local cur prev opts
    COMPREPLY=()
    cur=\"${{COMP_WORDS[COMP_CWORD]}\}"
    prev=\"${{COMP_WORDS[COMP_CWORD-1]}\}"
    opts=\"{' '.join(commands)}\"

    case ${{prev}} in
"

        # Add command completions
        for command in commands:
            completion_script += f"        {command})
            opts=\"{' '.join(command_options[command])}\"
            ;;

"

        completion_script += """
        *)
            ;;
    esac

    COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
    return 0
}
complete -F _borgmatic_completion borgmatic
"""

        return completion_script

    except Exception as e:
        sys.stderr.write(f"An error occurred while generating the bash completion script: {e}\n")
        return ""

