def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    try:
        # Try to convert the whole string to an integer first
        return int(size)
    except ValueError:
        # If not, check for suffix
        suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
        if len(size) > 1 and size[-1] in suffixes:
            multiplier = suffixes[size[-1]]
            try:
                return int(size[:-1]) * multiplier
            except ValueError:
                raise ValueError("Invalid format for size string")
        else:
            raise ValueError("Invalid format for size string")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        if not size:
            raise ValueError("Input size cannot be empty")

        suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
        size = size.strip()

        if size[-1].isalpha():
            number_part = size[:-1]
            suffix_part = size[-1]
        else:
            number_part = size
            suffix_part = ''

        try:
            number = float(number_part)
        except ValueError:
            raise ValueError(f"Invalid number part in size: {number_part}")

        multiplier = suffixes.get(suffix_part.upper(), 1)
        return int(number * multiplier)

    except Exception as e:
        raise ValueError(f"Failed to convert size '{size}': {e}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
    size = size.strip()
    if size.isdigit():
        return int(size)
    try:
        if size[-1].upper() in suffixes:
            return int(size[:-1]) * suffixes[size[-1].upper()]
        else:
            raise ValueError("Invalid suffix")
    except (ValueError, IndexError):
        raise ValueError("Invalid size format")

