    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) for char in alphabet) or not alphabet:
        raise ValueError("Alphabet must be a non-empty list of strings.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer.")

    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one character.")

    if number == 0:
        return alphabet[0] * padding if padding is not None else alphabet[0]

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    result_str = ''.join(reversed(result))

    if padding is not None:
        result_str = result_str.zfill(padding)

    return result_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative.")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))
    if padding:
        result = result.rjust(padding, alphabet[0])

    return result

