def get_repo_archive(url: str, destination_path: Path) -> Path:
    import os
    import tarfile

    try:
        response = requests.get(url)
        response.raise_for_status()  # Raise an error for bad responses
    except requests.RequestException as e:
        raise Exception(f"Failed to download archive from {url}: {e}")

    try:
        with tarfile.open(fileobj=response.raw, mode='r|gz') as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as e:
        raise Exception(f"Failed to extract archive: {e}")
    except Exception as e:
        raise Exception(f"An error occurred while extracting the archive: {e}")

    # Assuming the tar contains a top-level directory, return its path
    try:
        extracted_dir = next(destination_path.iterdir())
        return extracted_dir
    except StopIteration:
        raise Exception("The archive is empty or did not extract as expected")
    except Exception as e:
        raise Exception(f"Could not determine the extracted directory: {e}")

