def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os
    import re

    def posix_split(s):
        return re.findall(r"""((?:[^\s\\]|\\.)+)""", s)

    def windows_split(s):
        return re.findall(r"""(?:[^\s"]+|"[^"]*")""", s)

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        return posix_split(s)
    elif platform == 0:
        return windows_split(s)
    else:
        raise ValueError("Invalid platform specified. Use 'this', 1, or 0.")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os
    import re

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        # POSIX
        pattern = r'''(?u)(?:(?P<quote>['"])(.*?)(?P=quote)|(\S+))'''
    elif platform == 0:
        # Windows/CMD
        pattern = r'''(?u)(?:"([^"]*)"|'([^']*)'|(\\ |\S)+)'''
        backslash_pattern = re.compile(r'\\(.)')
    else:
        raise ValueError("Unsupported platform value")

    try:
        matches = re.finditer(pattern, s)
        result = []
        for match in matches:
            if match.group('quote'):
                # Remove the quotes
                result.append(match.group(2))
            elif match.group(3):
                result.append(match.group(3))
            elif platform == 0:
                # For Windows, handle escaped characters
                result.append(backslash_pattern.sub(r'\1', match.group(0)))
            else:
                result.append(match.group(0))
        return result
    except Exception as e:
        raise ValueError(f"Error splitting string: {e}")

def split(s, platform='this'):
    if platform == 'this':
        import sys
        platform = 1 if sys.platform.startswith('win') else 0

    if platform == 1:  # POSIX
        # Regex for splitting POSIX command line arguments
        regex = r"""(['"])(.*?)\1|\S+"""
    elif platform == 0:  # Windows/CMD
        # Regex for splitting Windows command line arguments
        regex = r'(?:"(.*?)(?:"|$)|()(.*?)(?=\s|$|"))'
    else:
        raise ValueError("Unsupported platform. Use 'this', 1, or 0.")

    try:
        return [m.group(2) or m.group(3) or m.group(1) for m in re.finditer(regex, s)]
    except TypeError:
        raise TypeError("Input must be a string.")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive at {archive_path} does not exist.")

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)

    try:
        if filename:
            output_path = tmp_path / filename
        else:
            output_path = tmp_path / os.path.basename(archive_path)

        if archive_path.endswith(('.tar.gz', '.tgz')):
            subprocess.run(['tar', '-xzf', archive_path, '-C', tmp_path], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', tmp_path], check=True)
        else:
            raise ValueError(f"Unsupported archive format for file: {archive_path}")

        return f"file://{output_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = set()
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) > 2:
                ignored_files.add(parts[-1])

        # Sort the list of ignored files
        sorted_files = sorted(ignored_files)

        # Return the sorted list as a single string with filenames separated by commas
        return ','.join(sorted_files)

    except subprocess.CalledProcessError as e:
        # Handle the case where the git command fails
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        # Handle any other exceptions
        return f"An error occurred: {str(e)}"

