def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or list of strings representing the script.
    :param separator: A string used to separate commands in the one-liner.
    :return: A string containing the one-liner command.
    """
    try:
        if isinstance(script, str):
            script = script.splitlines()
        elif not isinstance(script, list):
            raise ValueError("Script must be a string or a list of strings.")

        # Filter out empty lines
        script = [line.strip() for line in script if line.strip()]

        return separator.join(script)
    except Exception as e:
        raise ValueError(f"An error occurred while converting the script to a one-liner: {e}")

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or list of strings representing the script commands.
    :param seperator: A string to separate the commands in the one-liner.
    :return: A single string with all commands concatenated by the separator.
    """
    if not script:
        return ""

    if isinstance(script, str):
        script = script.splitlines()

    try:
        return seperator.join(command.strip() for command in script if command.strip())
    except Exception as e:
        raise ValueError("An error occurred while processing the script: " + str(e))

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os
    import pickle
    import sys
    import base64

    def run_func_with_args(func, args):
        return func(*args)

    # Serialize the function and arguments
    func_name = f"{func.__module__}.{func.__name__}"
    serialized_args = base64.b64encode(pickle.dumps(args)).decode('utf-8')

    # Construct the command to run the function
    command = [sys.executable, '-c', f"""
import base64
import pickle
import {func.__module__}

def run_func_with_args(func_name, args):
    func = getattr({func.__module__}, func_name)
    args = pickle.loads(base64.b64decode(args.encode('utf-8')))
    return func(*args)

run_func_with_args('{func_name}', '{serialized_args}')
"""]

    # Set up environment for subprocess
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True,
            env=env,
            timeout=timeout
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError(f"Process timed out after {timeout} seconds")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Process failed with code {e.returncode}: {e.stderr}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {str(e)}")

