def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        for subj, pred, obj in graph:
            if pred == prop:
                # If something is a child, it cannot be a root
                if subj in roots:
                    roots.remove(subj)
                # If the parent is not a child of anyone, it is a potential root
                if obj not in graph.subjects(predicate=prop):
                    roots.add(obj)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

