def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    from configparser import ConfigParser, ParsingError

    if not isinstance(config_filenames, (list, tuple)):
        raise ValueError("config_filenames must be a list or tuple of filenames.")

    if overrides is not None and not isinstance(overrides, dict):
        raise ValueError("overrides must be a dictionary or None.")

    configs = {}
    log_records = []

    for filename in config_filenames:
        if not isinstance(filename, str):
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Invalid filename type: {type(filename)}. Expected str."
            }))
            continue

        if not os.path.isfile(filename):
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"File not found: {filename}"
            }))
            continue

        config = ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
            if resolve_env:
                config = _resolve_env_vars(config)
            if overrides:
                config = _apply_overrides(config, overrides)
            configs[filename] = config
        except ParsingError as e:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Error parsing {filename}: {e}"
            }))

    return configs, log_records

def _resolve_env_vars(config):
    import re
    env_var_pattern = re.compile(r'\$\{(\w+)\}')

    def replace_env_vars(value):
        def replace_match(match):
            env_var = match.group(1)
            return os.environ.get(env_var, match.group(0))
        return env_var_pattern.sub(replace_match, value)

    for section in config.sections():
        for option in config.options(section):
            config.set(section, option, replace_env_vars(config.get(section, option)))
    return config

def _apply_overrides(config, overrides):
    for section, settings in overrides.items():
        if isinstance(settings, dict):
            for option, value in settings.items():
                if config.has_section(section):
                    config.set(section, option, str(value))
                else:
                    log_records.append(logging.makeLogRecord({
                        'levelno': logging.WARNING,
                        'levelname': 'WARNING',
                        'msg': f"Cannot apply override for non-existent section: {section}"
                    }))
        else:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.WARNING,
                'levelname': 'WARNING',
                'msg': f"Overrides for section {section} must be a dictionary."
            }))
    return config

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if not isinstance(config_filenames, (list, tuple)):
        raise ValueError("config_filenames must be a list or tuple of filenames.")

    if overrides is not None and not isinstance(overrides, dict):
        raise ValueError("overrides must be a dictionary.")

    configurations = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                configurations[filename] = config
        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=None, exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Failed to decode JSON from {filename}: {str(e)}", args=None, exc_info=True))
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"An error occurred while loading {filename}: {str(e)}", args=None, exc_info=True))

    if overrides:
        for config in configurations.values():
            config.update(overrides)

    if resolve_env:
        for config in configurations.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    config[key] = os.getenv(env_var, value)

    return configurations, log_records

