def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import configparser
    import os

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    def resolve_environment_variables(config):
        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    config.set(section, key, os.path.expandvars(value))
        return config

    def parse_config(filename):
        try:
            config = configparser.ConfigParser()
            with open(filename, 'r') as file:
                config.read_file(file)
            config = resolve_environment_variables(config)
            config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except Exception as e:
            record = logging.LogRecord(
                name='ConfigLoader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=None,
                exc_info=True
            )
            log_records.append(record)

    for filename in config_filenames:
        if isinstance(filename, str) and os.path.isfile(filename):
            parse_config(filename)
        else:
            log_records.append(
                logging.LogRecord(
                    name='ConfigLoader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"File not found or invalid: {filename}",
                    args=None,
                    exc_info=None
                )
            )

    # Apply overrides
    for section, settings in overrides.items():
        for key, value in settings.items():
            if section not in config_dict:
                config_dict[section] = {}
            config_dict[section][key] = value

    return config_dict, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

    seconds, nanoseconds = divmod(ticks, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)

    return cls(hour=hours, minute=minutes, second=seconds, microsecond=nanoseconds // 1000, tzinfo=tz)

