                iface_argspec = getfullargspec(iface_method)
                if candidate_argspec != iface_argspec:
                    errors.append(f"Candidate's {name} has incorrect signature")
            except Exception as e:
                errors.append(f"Error checking signature for {name}: {str(e)}")

    # Check for necessary attributes
    for name in iface.names(all=True):
        iface_attr = iface.getAttribute(name)
        if iface_attr is None:
            continue  # Skip methods, they are checked earlier
        if not hasattr(candidate, name):
