def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    if not isinstance(text, str):
        raise ValueError("Input text must be a string.")

    # Regular expression to find tags
    tag_pattern = r'(?<!`)(?:^|\s)(#\w+)(?!\w)(?!`)'  # Tags not inside code blocks

    # Find all tags
    matches = re.finditer(tag_pattern, text)

    for match in matches:
        tag = match.group(0).strip()
        tags.add(tag)
        if replacer:
            if not callable(replacer):
                raise ValueError("Replacer must be a callable function.")
            try:
                replacement = replacer(tag)
                text = text[:match.start()] + replacement + text[match.end():]
            except Exception as e:
                raise RuntimeError(f"Error in replacer function: {str(e)}")

    # Clean up multiple spaces that might have been created from replacements
    text = re.sub(r'\s+', ' ', text).strip()

    return tags, text

