    # Find all tags in the text
    tags = set(tag_pattern.findall(text))

    # If a replacer is provided, replace tags in the text
    if replacer:
        def replace_tag(match):
            tag = match.group(0)
            try:
                return replacer(tag)
            except Exception as e:
                # Handle exceptions from the replacer function
                print(f"Error replacing {tag}: {e}")
                return tag

        text = tag_pattern.sub(replace_tag, text)

    return tags, text

