                tag = element.tag[element.tag.find('}') + 1:]  # Remove namespace
                if tag not in xrd_dict:
                    xrd_dict[tag] = []
                xrd_dict[tag].append({attr: element.attrib[attr] for attr in element.attrib})
                if element.text and element.text.strip():
                    xrd_dict[tag][-1]['value'] = element.text.strip()

            # Flatten lists with single item
            for key in xrd_dict:
                if len(xrd_dict[key]) == 1:
                    xrd_dict[key] = xrd_dict[key][0]

            return xrd_dict
        except (ExpatError, ET.ParseError):
            raise ValueError("The document is neither valid JSON nor XRD XML.")
